import{_ as e,o as t,c as o,a5 as r}from"./chunks/framework.DJo0M80U.js";const c=JSON.parse('{"title":"16计算日期到天数转换","description":"简单 通过率：38.02% 时间限制：1秒 空间限制：32M 知识点 字符串 思维 描述 根据输入的日期，计算是这一年的第几天。 保证年份为4位数且日期合法。 进阶：时间复杂度：�(�) O ( n ) ，空间复杂度：�(1) O (1) 输入描述： 输入一行，每行空格分割，分别。","frontmatter":{"title":"16计算日期到天数转换","date":"2026-08-11T00:00:00.000Z","categories":["前端面试与实战"],"tags":["前端面试","算法","求职","教程","OneNote","算法训练"],"description":"简单 通过率：38.02% 时间限制：1秒 空间限制：32M 知识点 字符串 思维 描述 根据输入的日期，计算是这一年的第几天。 保证年份为4位数且日期合法。 进阶：时间复杂度：�(�) O ( n ) ，空间复杂度：�(1) O (1) 输入描述： 输入一行，每行空格分割，分别。","sidebarWeight":50,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/a-吊打面试官/算法题/华为简单[31个]/16计算日期到天数转换.md"},"headers":[],"relativePath":"posts/前端面试与实战/03-算法训练/华为简单[31个]/16计算日期到天数转换.md","filePath":"posts/前端面试与实战/03-算法训练/华为简单[31个]/16计算日期到天数转换.md"}'),n={name:"posts/前端面试与实战/03-算法训练/华为简单[31个]/16计算日期到天数转换.md"};function s(d,a,i,_,l,p){return t(),o("div",null,[...a[0]||(a[0]=[r('<div><h1 id="_16计算日期到天数转换" tabindex="-1">16计算日期到天数转换 <a class="header-anchor" href="#_16计算日期到天数转换" aria-label="Permalink to &quot;16计算日期到天数转换&quot;">​</a></h1><blockquote><p>本节目标：理解“16计算日期到天数转换”的核心思路，并能把它用于实际开发或面试表达。 简单 通过率：38.02% 时间限制：1秒 空间限制：32M 知识点==字符串====思维== <strong>描述</strong> 根据输入的日期，计算是这一年的第几天。 保证年份为4位数且日期合法。 进阶：时间复杂度：�(�) <em>O</em>(<em>n</em>) ，空间复杂度：�(1) <em>O</em>(1) <strong>输入描述：</strong> 输入一行，每行空格分割，分别是年，月，日 <strong>输出描述：</strong> 输出是这一年的第几天 <strong>示例1</strong> 输入： 2012 12 31 ==复制== 输出： 366 ==复制== <strong>示例2</strong> 输入： 1982 3 4 ==复制== 输出： 63</p></blockquote><p>为了计算给定日期是一年中的第几天，我们需要知道每个月的天数，以及如何处理闰年。在闰年中，二月有29天，而非闰年有28天。一个年份是闰年的条件是它能被4整除但不能被100整除，或者它能被400整除。</p><p>以下是如何实现这个逻辑的步骤：</p><ol><li><strong>确定每个月的天数</strong>：创建一个包含每个月天数的列表，考虑非闰年的情况。</li><li><strong>判断是否为闰年</strong>：如果是闰年，将二月的天数调整为29天。</li><li><strong>计算日期是一年中的第几天</strong>：根据输入的月份，累加之前所有月份的天数，再加上输入的日数。</li></ol><p>这里是实现的代码： def is_leap_year(year): &quot;&quot;&quot;判断是否为闰年&quot;&quot;&quot; return year % 4 == 0 and year % 100 != 0 or year % 400 == 0</p><p>def day_of_year(year, month, day):</p><h1 id="每个月的天数-注意二月是按照非闰年来设置的" tabindex="-1">每个月的天数，注意二月是按照非闰年来设置的 <a class="header-anchor" href="#每个月的天数-注意二月是按照非闰年来设置的" aria-label="Permalink to &quot;每个月的天数，注意二月是按照非闰年来设置的&quot;">​</a></h1><p>days_of_month = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]</p><h1 id="如果是闰年-二月改为29天" tabindex="-1">如果是闰年，二月改为29天 <a class="header-anchor" href="#如果是闰年-二月改为29天" aria-label="Permalink to &quot;如果是闰年，二月改为29天&quot;">​</a></h1><p>if is_leap_year(year): days_of_month[1] = 29</p><h1 id="计算第几天" tabindex="-1">计算第几天 <a class="header-anchor" href="#计算第几天" aria-label="Permalink to &quot;计算第几天&quot;">​</a></h1><p>return sum(days_of_month[:month-1]) + day</p><h1 id="输入" tabindex="-1">输入 <a class="header-anchor" href="#输入" aria-label="Permalink to &quot;输入&quot;">​</a></h1><p>year, month, day = map(int, input().split())</p><h1 id="输出" tabindex="-1">输出 <a class="header-anchor" href="#输出" aria-label="Permalink to &quot;输出&quot;">​</a></h1><p>print(day_of_year(year, month, day))</p><p>这段代码首先定义了一个<code>is_leap_year</code>函数来判断输入的年份是否为闰年。然后<code>day_of_year</code>函数使用<code>days_of_month</code>列表存储每个月的天数，通过累加到输入月份之前的所有月份的天数，并加上输入的日数来计算结果。如果输入的年份是闰年，会将二月的天数调整为29天。</p><p>这个方法的时间复杂度为O(1)，因为无论输入如何，它所进行的计算步骤数量是固定的。空间复杂度也是O(1)，因为所使用的额外空间不随输入数据的大小而改变。</p></div>',1)])])}const m=e(n,[["render",s]]);export{c as __pageData,m as default};
